import json
d=json.load(open('hig-a11y.json'))
out=[]
def walk(n):
    if isinstance(n,dict):
        t=n.get('type')
        if t=='text': out.append(n.get('text',''))
        elif t=='codeVoice': out.append('\`'+n.get('code','')+'\`')
        elif t=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif t=='paragraph':
            out.append('\n')
            for c in n.get('inlineContent',[]): walk(c)
        elif t=='listItem':
            out.append('\n- ')
            for c in n.get('content',[]): walk(c)
        else:
            for k,v in n.items():
                if k in ('inlineContent','content','primaryContentSections','sections','items','variants'): walk(v)
    elif isinstance(n,list):
        for i in n: walk(i)
walk(d)
open('hig.txt','w').write(''.join(out))
print(len(''.join(out)))
"

